<script setup lang="ts">
import {computed} from 'vue';import {state,dispatch,modal} from './store';import {storageStyle} from '../content/storage';import {containerItems} from '../game/containers';import {buyerRemaining} from '../game/demand';import StorageArt from '../scenes/StorageArt.vue';
const visitor=computed(()=>state.value.visitors[state.value.visitorIndex]);
const boxes=computed(()=>state.value.containers??[]);
function store(){modal.value='';}
</script>
<template><section v-if="visitor?.kind==='seller'&&visitor.storageGoods?.length" class="storage-offers"><header><span>卖家带来的箱包</span><small>外形占格 / 内部空间</small></header><article v-for="offer in visitor.storageGoods" :key="offer.id" :data-storage-offer="offer.id"><StorageArt :kind="storageStyle(offer.styleId).art"/><div><h3>{{storageStyle(offer.styleId).name}}</h3><p>{{storageStyle(offer.styleId).footprint.width}}×{{storageStyle(offer.styleId).footprint.height}} 外形 · {{storageStyle(offer.styleId).columns}}×{{storageStyle(offer.styleId).rows}} 内仓</p><button :disabled="state.cash<offer.price" @click="dispatch({type:'buyStorage',visitorId:visitor.id,offerId:offer.id})">买下箱包 · ₡{{offer.price}}</button></div></article></section><section v-else-if="visitor?.kind==='buyer'&&boxes.length" class="storage-offers"><header><span>转卖空箱包</span><small>占用一件采购数量与剩余预算</small></header><article v-for="box in boxes" :key="box.id"><StorageArt :kind="storageStyle(box.styleId).art"/><div><h3>{{box.label}}</h3><button :disabled="buyerRemaining(visitor)<1 || containerItems(state,box.id).length>0 || (visitor.budget??400)<Math.round(storageStyle(box.styleId).price*.55)" @click="dispatch({type:'sellStorage',visitorId:visitor.id,storageId:box.id})">{{containerItems(state,box.id).length?'先清空箱包':`出售箱包 · ₡${Math.round(storageStyle(box.styleId).price*.55)}`}}</button></div></article></section><button v-if="boxes.some(c=>c.location==='counter')" class="store-purchased-box" @click="store">返回柜台收纳 ↗</button></template>
<style scoped>.storage-offers{margin-top:18px;border-top:1px solid #3b6a7277;padding-top:14px}.storage-offers header{display:flex;justify-content:space-between;font-size:12px;color:#9bced0;margin-bottom:9px}.storage-offers header small{font-size:9px;color:#7babb5}.storage-offers article{display:flex;align-items:center;gap:15px;padding:12px;background:#152c36;border:1px solid #35606b66;margin-bottom:8px}.storage-offers img{width:75px;height:75px}.storage-offers h3{font-size:13px;color:#d5dccc;margin:0 0 6px}.storage-offers p{font-size:10px;color:#95bbc0;margin:0 0 8px}.storage-offers button{font-size:11px;padding:6px 10px}.store-purchased-box{font-size:11px;margin-top:12px;border-color:#81bec5;color:#9bd5d9}@media(max-height:550px){.storage-offers img{width:52px;height:52px}.storage-offers article{padding:8px;gap:10px}.storage-offers h3{font-size:12px}.storage-offers button{min-height:30px}}</style>
